    "cssVarsLabel": "CSS 変数",
    "jsHint": "JS は Vue コンポーネントの setup 戻り値としてオブジェクトを return する必要があります。バックエンド API の呼び出しには ctx.api.get('/me') を使用します。保存後、ポータルページにアクセスして実際の表示を確認してください。",
    "ctxApiRefBody": "ctx.ref(val)              — リアクティブ変数を作成\nctx.computed(fn)          — 算出プロパティを作成\nctx.watch(src, cb)        — 変更を監視\nctx.onMounted(fn)         — コンポーネントのマウント時\nctx.onUnmounted(fn)       — コンポーネントのアンマウント時\n\nctx.data.client           — ユーザーアカウント情報（リアクティブ）\nctx.data.token            — 現在の token（リアクティブ）\nctx.data.isDark           — ダークモード（リアクティブ）\n\nctx.api.get(path, query)  — GET リクエスト\nctx.api.post(path, body)  — POST リクエスト\nctx.api.put(path, body)   — PUT リクエスト\nctx.api.delete(path)      — DELETE リクエスト\n\nctx.formatBytes(bytes)    — ファイルサイズを整形\nctx.formatDate(date)       — 日付を整形\nctx.copyText(text)         — クリップボードにコピー\nctx.elMessage             — Element Plus メッセージ通知\nctx.config                — ポータル設定 (PORTAL_CONFIG)\nctx.moduleId              — 現在のモジュール ID\nctx.moduleTitle           — 現在のモジュールタイトル",
